using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Exploration of abstract structures, quantities, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and critical analysis of texts." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Understanding the fundamental laws of the universe." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Examination of past events and their impact on the present." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented principles.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace has 15 years of experience in software engineering education and specializes in introductory programming pedagogy.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, CourseCode = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. Alan Turing", InstructorBio = "Dr. Turing is a renowned researcher in computational theory with over 50 publications.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, CourseCode = "CS 301", Title = "Database Systems", Description = "Relational database design, SQL, normalization, and introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Edgar Codd", InstructorBio = "Dr. Codd pioneered relational database theory and brings decades of industry experience." },
            new() { Id = 4, DepartmentId = 2, CourseCode = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Euler Bernoulli", InstructorBio = "Dr. Bernoulli has taught mathematics for 20 years and is passionate about making calculus accessible.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is an expert in abstract algebra and its applications to physics and computer science." },
            new() { Id = 6, DepartmentId = 3, CourseCode = "ENG 101", Title = "College Composition", Description = "Develop effective writing skills for academic and professional contexts.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. Virginia Woolf", InstructorBio = "Prof. Woolf is an award-winning author and writing instructor with a focus on narrative craft." },
            new() { Id = 7, DepartmentId = 3, CourseCode = "ENG 220", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", InstructorName = "Prof. Mark Twain", InstructorBio = "Prof. Twain specializes in 19th-century American literature and humor studies.", IsFeatured = true },
            new() { Id = 8, DepartmentId = 4, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based approach with lab component.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:50 PM", InstructorName = "Dr. Richard Feynman", InstructorBio = "Dr. Feynman is known for making complex physics concepts understandable through vivid examples." },
            new() { Id = 9, DepartmentId = 4, CourseCode = "PHYS 201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM + Fri Lab 10:00 AM–12:50 PM", InstructorName = "Dr. James Maxwell", InstructorBio = "Dr. Maxwell has extensive research experience in electromagnetic theory and optics." },
            new() { Id = 10, DepartmentId = 5, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations and developments from prehistory through the Renaissance.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", InstructorName = "Prof. Herodotus Smith", InstructorBio = "Prof. Smith is a historian specializing in ancient civilizations and cross-cultural exchange." },
            new() { Id = 11, DepartmentId = 5, CourseCode = "HIST 205", Title = "Modern European History", Description = "European history from the Enlightenment through the 20th century.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Prof. Hannah Arendt", InstructorBio = "Prof. Arendt is a political historian focused on 20th-century European intellectual history." },
        };

        // Link departments to courses
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
        }
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

